  const layoutId = `${attr(child(docPoint, "prSet"), "loTypeId") ?? ""} ${attr(layoutRoot, "uniqueId") ?? ""}`.toLowerCase();
  const layout = layoutId.includes("hierarchy") || layoutId.includes("orgchart") ? "hierarchy" : layoutId.includes("cycle") ? "cycle" : layoutId.includes("list") ? "list" : "process";
