var table = null;
function build() {
  const out = [];
  let prev = 0;
  for (const part of RANGES.split(",")) {
    const [d, len] = part.split(".").map((s) => parseInt(s, 16));
    const a = prev + d;
    out.push([a, a + len]);
    prev = a + len;
  }
  return out;
}
function minchoCovers(cp) {
  if (cp < 13312 || cp > 64255) return true;
  if (!table) table = build();
  let lo = 0;
  let hi = table.length - 1;
  while (lo <= hi) {
    const mid = lo + hi >> 1;
    const [a, b] = table[mid];
    if (cp < a) hi = mid - 1;
    else if (cp > b) lo = mid + 1;
    else return true;
  }
  return false;
}
